\begin{align*}
x_1 = e^{32\log{15}} \\
y_1 = e^{-72\log{2}}
\end{align*}
For $a = 2\log{15}$ and $b = 18\log{2}$:
\begin{align*}
x_2 = e^{2\log{15}} \\
y_2 = e^{18\log{2}}
\end{align*}

